import { useState } from 'react';

const MAX_PHONES = 3;
const newPhone = () => ({ id: crypto.randomUUID(), number: '' });

export function PhonesField() {
  const [phones, setPhones] = useState(() => [newPhone()]);

  const update = (id, number) => setPhones((list) => list.map((p) => (p.id === id ? { ...p, number } : p)));
  const remove = (id) => setPhones((list) => list.filter((p) => p.id !== id));

  return (
    <fieldset>
      <legend>Telefony kontaktowe</legend>
      {phones.map((phone, i) => (
        <div key={phone.id}>
          <label htmlFor={phone.id}>Telefon {i + 1}</label>
          <input id={phone.id} type="tel" value={phone.number} onChange={(e) => update(phone.id, e.target.value)} />
          <button type="button" disabled={phones.length === 1} onClick={() => remove(phone.id)}>Usuń</button>
        </div>
      ))}
      <button type="button" disabled={phones.length >= MAX_PHONES} onClick={() => setPhones((list) => [...list, newPhone()])}>
        Dodaj numer
      </button>
    </fieldset>
  );
}

